{
  "name": "StarJar - Kids Reward Tracker",
  "description": "A fun and engaging app to track reward points for children. Manage profiles, log activities, and redeem rewards with a coin sound effect.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Child {
  id: string;
  name: string;
  avatarUrl: string; // Base64 or URL
  totalPoints: number;
}

export interface ActivityLog {
  id: string;
  childId: string;
  description: string;
  points: number; // Positive for earning, negative for redeeming
  timestamp: number;
  category: 'chore' | 'behavior' | 'redemption' | 'other';
}

export interface ActivitySuggestion {
  description: string;
  points: number;
  category: ActivityLog['category'];
}

import { Child, ActivityLog } from '../types';

const KIDS_KEY = 'starjar_kids';
const LOGS_KEY = 'starjar_logs';

export const getChildren = (): Child[] => {
  try {
    const data = localStorage.getItem(KIDS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Failed to load children", e);
    return [];
  }
};

export const saveChildren = (children: Child[]) => {
  localStorage.setItem(KIDS_KEY, JSON.stringify(children));
};

export const getLogs = (): ActivityLog[] => {
  try {
    const data = localStorage.getItem(LOGS_KEY);
    return data ? JSON.parse(data) : [];
  } catch (e) {
    console.error("Failed to load logs", e);
    return [];
  }
};

export const saveLogs = (logs: ActivityLog[]) => {
  localStorage.setItem(LOGS_KEY, JSON.stringify(logs));
};

export const addLogEntry = (log: ActivityLog) => {
  const logs = getLogs();
  const children = getChildren();

  // Update logs
  logs.push(log);
  saveLogs(logs);

  // Update child total
  const childIndex = children.findIndex(c => c.id === log.childId);
  if (childIndex >= 0) {
    children[childIndex].totalPoints += log.points;
    saveChildren(children);
  }
};

export const deleteChildData = (childId: string) => {
  let children = getChildren();
  let logs = getLogs();

  children = children.filter(c => c.id !== childId);
  logs = logs.filter(l => l.childId !== childId);

  saveChildren(children);
  saveLogs(logs);
};

import { GoogleGenAI, Type } from "@google/genai";
import { ActivitySuggestion } from "../types";

const apiKey = process.env.API_KEY;

export const suggestActivity = async (input: string): Promise<ActivitySuggestion | null> => {
  if (!apiKey) return null;

  try {
    const ai = new GoogleGenAI({ apiKey });

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Suggest a standardized activity name, point value, and category for a child's activity described as: "${input}". 
      If it sounds like a chore or good behavior, points should be positive (1-100). 
      If it sounds like a redemption (buying a toy, screen time), points should be negative.
      Be fair and consistent.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            description: { type: Type.STRING, description: "A clean, short title for the activity (e.g. 'Washed Dishes')" },
            points: { type: Type.INTEGER, description: "The suggested point value (positive or negative)" },
            category: { 
              type: Type.STRING, 
              enum: ['chore', 'behavior', 'redemption', 'other'],
              description: "The category of the activity" 
            }
          },
          required: ["description", "points", "category"]
        }
      }
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text) as ActivitySuggestion;

  } catch (error) {
    console.error("Gemini AI Error:", error);
    return null;
  }
};

import React, { useMemo } from 'react';
import { ActivityLog } from '../types';
import { Calendar, Trash2 } from 'lucide-react';

interface HistoryViewProps {
  logs: ActivityLog[];
}

const HistoryView: React.FC<HistoryViewProps> = ({ logs }) => {
  const groupedLogs = useMemo(() => {
    const groups: Record<string, ActivityLog[]> = {};

    // Sort descending
    const sorted = [...logs].sort((a, b) => b.timestamp - a.timestamp);

    sorted.forEach(log => {
      const date = new Date(log.timestamp);
      const key = `${date.getFullYear()}-${date.getMonth()}`; // e.g. "2023-9" for Oct 2023
      if (!groups[key]) groups[key] = [];
      groups[key].push(log);
    });

    return groups;
  }, [logs]);

  const getMonthName = (yearMonth: string) => {
    const [year, month] = yearMonth.split('-');
    const date = new Date(parseInt(year), parseInt(month));
    return date.toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
  };

  if (logs.length === 0) {
    return (
      <div className="text-center py-10 text-gray-400">
        <Calendar className="w-12 h-12 mx-auto mb-2 opacity-50" />
        <p>No activity recorded yet.</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {Object.keys(groupedLogs).map(key => (
        <div key={key} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">
          <div className="bg-slate-50 px-4 py-2 border-b border-slate-100 font-semibold text-slate-600 text-sm uppercase tracking-wider">
            {getMonthName(key)}
          </div>
          <div className="divide-y divide-slate-100">
            {groupedLogs[key].map(log => (
              <div key={log.id} className="flex items-center justify-between p-4 hover:bg-slate-50 transition-colors">
                <div className="flex items-center gap-3">
                  <div className={`w-2 h-10 rounded-full ${
                    log.points > 0 ? 'bg-green-400' : 'bg-rose-400'
                  }`}></div>
                  <div>
                    <p className="font-medium text-slate-800">{log.description}</p>
                    <p className="text-xs text-slate-500 capitalize">
                      {new Date(log.timestamp).toLocaleDateString(undefined, { day: 'numeric', weekday: 'short' })} • {log.category}
                    </p>
                  </div>
                </div>
                <div className={`text-lg font-bold ${log.points > 0 ? 'text-green-600' : 'text-rose-600'}`}>
                  {log.points > 0 ? '+' : ''}{log.points}
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
    </div>
  );
};

export default HistoryView;

import React, { useState, useEffect } from 'react';
import { X, Sparkles, Minus, Plus, Coins, Gift } from 'lucide-react';
import { suggestActivity } from '../services/ai';
import { ActivityLog } from '../types';

interface ActivityFormProps {
  childId: string;
  onSave: (log: Omit<ActivityLog, 'id' | 'timestamp'>) => void;
  onClose: () => void;
  mode: 'earn' | 'redeem';
}

const ActivityForm: React.FC<ActivityFormProps> = ({ childId, onSave, onClose, mode }) => {
  const [description, setDescription] = useState('');
  const [points, setPoints] = useState(10);
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [category, setCategory] = useState<'chore' | 'behavior' | 'redemption' | 'other'>(
    mode === 'earn' ? 'chore' : 'redemption'
  );

  const handleAiSuggest = async () => {
    if (!description.trim()) return;
    setIsAiLoading(true);
    const suggestion = await suggestActivity(description);
    setIsAiLoading(false);

    if (suggestion) {
      setDescription(suggestion.description);
      // Ensure points polarity matches mode
      const absPoints = Math.abs(suggestion.points);
      setPoints(absPoints);

      // If AI suggests a redemption category but we are in earn mode, or vice versa, warn or adapt?
      // For simplicity, we just take the category if valid, but enforce polarity logic on save
      if (mode === 'earn' && suggestion.points < 0) {
         // AI thinks it's a redemption, but we are in earn mode. 
         // We'll keep positive points but maybe switch category if needed.
      }
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const finalPoints = mode === 'redeem' ? -Math.abs(points) : Math.abs(points);
    onSave({
      childId,
      description,
      points: finalPoints,
      category
    });
    onClose();
  };

  const presetAmounts = [5, 10, 20, 50, 100];

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300">

        {/* Header */}
        <div className={`p-4 flex justify-between items-center ${mode === 'earn' ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}`}>
          <h2 className="text-xl font-bold flex items-center gap-2">
            {mode === 'earn' ? <Coins className="w-6 h-6" /> : <Gift className="w-6 h-6" />}
            {mode === 'earn' ? 'Add Points' : 'Redeem Reward'}
          </h2>
          <button onClick={onClose} className="p-1 hover:bg-black/10 rounded-full transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-6">

          {/* Description Input */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-600 block">Activity Name</label>
            <div className="relative">
              <input 
                type="text" 
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder={mode === 'earn' ? "e.g. Cleaned room, Finished homework" : "e.g. Bought a toy, 1 hour TV"}
                className="w-full pl-4 pr-12 py-3 border-2 border-slate-200 rounded-xl focus:border-indigo-500 focus:ring-0 outline-none text-lg transition-colors"
                autoFocus
                required
              />
              {process.env.API_KEY && (
                <button 
                  type="button"
                  onClick={handleAiSuggest}
                  disabled={isAiLoading || !description}
                  className="absolute right-2 top-2 p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition-colors disabled:opacity-50"
                  title="Auto-suggest points"
                >
                  <Sparkles className={`w-5 h-5 ${isAiLoading ? 'animate-spin' : ''}`} />
                </button>
              )}
            </div>
            {process.env.API_KEY && <p className="text-xs text-slate-400">Tip: Type activity and click ✨ for AI suggestions.</p>}
          </div>

          {/* Points Control */}
          <div className="space-y-2">
            <label className="text-sm font-semibold text-gray-600 block">Points</label>
            <div className="flex items-center gap-4">
              <button 
                type="button"
                onClick={() => setPoints(Math.max(1, points - 1))}
                className="p-4 rounded-xl bg-slate-100 hover:bg-slate-200 active:scale-95 transition-all text-slate-600"
              >
                <Minus className="w-6 h-6" />
              </button>

              <div className="flex-1 text-center">
                <span className={`text-5xl font-bold ${mode === 'earn' ? 'text-emerald-500' : 'text-rose-500'}`}>
                  {points}
                </span>
              </div>

              <button 
                type="button"
                onClick={() => setPoints(points + 1)}
                className="p-4 rounded-xl bg-slate-100 hover:bg-slate-200 active:scale-95 transition-all text-slate-600"
              >
                <Plus className="w-6 h-6" />
              </button>
            </div>

            {/* Presets */}
            <div className="flex gap-2 justify-center mt-2">
              {presetAmounts.map(amt => (
                <button
                  key={amt}
                  type="button"
                  onClick={() => setPoints(amt)}
                  className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
                    points === amt 
                      ? (mode === 'earn' ? 'bg-emerald-100 border-emerald-300 text-emerald-700' : 'bg-rose-100 border-rose-300 text-rose-700')
                      : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300'
                  }`}
                >
                  {amt}
                </button>
              ))}
            </div>
          </div>

          {/* Submit Button */}
          <button 
            type="submit" 
            className={`w-full py-4 rounded-xl text-white font-bold text-lg shadow-lg active:scale-[0.98] transition-all flex items-center justify-center gap-2 ${
              mode === 'earn' 
                ? 'bg-gradient-to-r from-emerald-400 to-teal-500 shadow-emerald-200' 
                : 'bg-gradient-to-r from-rose-400 to-pink-500 shadow-rose-200'
            }`}
          >
            {mode === 'earn' ? <Plus className="w-6 h-6" /> : <Minus className="w-6 h-6" />}
            {mode === 'earn' ? 'Add Points' : 'Redeem Points'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default ActivityForm;

import React from 'react';
