// Default / Fallback Data
const DEFAULT_BANKS: Bank[] = [
  {
    id: 'mbank',
    name: 'M-Bank',
    description: 'The Tiger Bank. Strong, steady, and safe.',
    color: 'bg-yellow-400 text-yellow-900',
