                const bank = banks.find(b => b.id === inv.bankId);
                const matureDate = new Date(inv.maturityDate);
                const progress = Math.min(100, Math.max(0, ((Date.now() - inv.startDate) / (inv.maturityDate - inv.startDate)) * 100));

